import ast


def score(program: str) -> float:
    try:
        ns = list(ast.walk(ast.parse(program)))
        kinds = len({type(x) for x in ns})
        return min(1.0, kinds / 40 + len(ns) / 400)
    except Exception:
        return 0.0

def score(program: str) -> float:
    n = len(program)
    k = sum(program.count(w) for w in ("def", "return", "for", "if", "len", "min", "max"))
    return min(1.0, (n + 20 * k) / 1500)

def score(program: str) -> float:
    words = set(program.split())
    k = len(words) + program.count("(") + program.count("\n")
    return k / (k + len(program) / 4 + 1.0)

import ast

def score(program: str) -> float:
    try:
        n = list(ast.walk(ast.parse(program)))
        k = len({type(x).__name__ for x in n})
        v = len({x.id for x in n if isinstance(x, ast.Name)})
        return min(1.0, (len(n) + 4 * k + 3 * v) / 400)
    except Exception:
        return 0.0

def score(program: str) -> float:
    n = len(program)
    if n == 0:
        return 0.0
    v = sum(c in "aeiou_" for c in program) / n
    l = min(n, 1500) / 1500
    return min(1.0, max(0.0, 0.5 * v * 3 + 0.5 * l))

